        private string GetEmailByNik(string nik)
        {
            string email = string.Empty;

            string path = ConfigurationManager.ConnectionStrings["dbpath"].ConnectionString;
            using (SqlConnection Con = new SqlConnection(path))
            {
                SqlCommand sqlcomm = new SqlCommand();
                sqlcomm.CommandText = "sp_PROCUREMENT_DB_Purchase";
                sqlcomm.CommandType = CommandType.StoredProcedure;
                sqlcomm.Connection = Con;
                sqlcomm.Parameters.AddWithValue("@StatementType", "GetEmailByNik");
                sqlcomm.Parameters.AddWithValue("@nik_approver", nik);

                try
                {
                    Con.Open();
                    SqlDataReader dr = sqlcomm.ExecuteReader();

                    if (dr.Read())
                    {
                        email = dr["email_karyawan"].ToString();
                    }

                    dr.Close();
                }
                catch (Exception err)
                {
                    //TODO: Handle the exception
                }
            }

            return email;
        }

        protected async void btnUpdateApproval_Click(object sender, EventArgs e)
        {
            if (Session["status_approve"].ToString() == "Price Checked")
            {
                if (ddlManagerDivision.SelectedItem.Text != "")
                {
                    string path = ConfigurationManager.ConnectionStrings["dbpath"].ConnectionString;
                    SqlConnection Con = new SqlConnection(path);
                    Con.Open();
                    SqlCommand sqlcomm = new SqlCommand();
                    sqlcomm.CommandText = "sp_PROCUREMENT_DB_Purchase";
                    sqlcomm.CommandType = CommandType.StoredProcedure;
                    sqlcomm.Connection = Con;
                    sqlcomm.Parameters.AddWithValue("@StatementType", "UpdateMGRApproverRF");
                    sqlcomm.Parameters.AddWithValue("@rf_no", lbRFNumberBreadcrumb.Text.Trim());
                    sqlcomm.Parameters.AddWithValue("@nik_approver", ddlManagerDivision.SelectedValue);

                    sqlcomm.ExecuteNonQuery();
                    //Page.ClientScript.RegisterStartupScript(this.GetType(), "text", "AddItemsSuccess();", true);
                    await SendEmailSendToManagerDivision();
                    sqlcomm.Dispose();
                    Con.Close();
                    Con.Dispose();
                }
                else
                {
                    ScriptManager.RegisterStartupScript(this, this.GetType(), "toastrMessage", "toastr.error('Update Failed!, Please select Approver!!');", true);
                }
            }
            else if (Session["status_approve"].ToString() == "Approved (Division Manager)")
            {
                if (ddlGMDivision.SelectedItem.Text != "")
                {
                    string path = ConfigurationManager.ConnectionStrings["dbpath"].ConnectionString;
                    SqlConnection Con = new SqlConnection(path);
                    Con.Open();
                    SqlCommand sqlcomm = new SqlCommand();
                    sqlcomm.CommandText = "sp_PROCUREMENT_DB_Purchase";
                    sqlcomm.CommandType = CommandType.StoredProcedure;
                    sqlcomm.Connection = Con;
                    sqlcomm.Parameters.AddWithValue("@StatementType", "UpdateGMApproverRF");
