                    ReportViewerPurchase.LocalReport.Refresh();

                    string FileName = lbRFNumberBreadcrumb.Text.Trim() + ".pdf";
                    string extension;
                    string encoding;
                    string mimeType;
                    string[] streams;
                    Warning[] warnings;
