        protected async void btnSend_Click(object sender, EventArgs e)
        {
            string path = ConfigurationManager.ConnectionStrings["dbpath"].ConnectionString;
            SqlConnection Con = new SqlConnection(path);
            Con.Open();
            SqlCommand sqlcomm = new SqlCommand();
            sqlcomm.CommandText = "sp_PROCUREMENT_DB_Purchase";
            sqlcomm.CommandType = CommandType.StoredProcedure;
            sqlcomm.Connection = Con;
            sqlcomm.Parameters.AddWithValue("@StatementType", "Updatesendpur");
            sqlcomm.Parameters.AddWithValue("@rf_no", lbRFNumberBreadcrumb.Text.Trim());
          
            sqlcomm.ExecuteNonQuery();

            await SendEmailToPurchasingCheckEstimatePrice();
            sqlcomm.Dispose();
            Con.Close();


        }

        protected async void btnCancelRF_Click(object sender, EventArgs e)
        {
            if (Session["status_approve"].ToString() == "Approved (Fully Approved)" && Session["status"].ToString() == "Complete")
            {
                ScriptManager.RegisterStartupScript(this, this.GetType(), "toastrMessage", "toastr.error('Cannot be Canceled!, RF has been Completed.');", true);
            }
            else if (Session["status_approve"].ToString() == "Approved (Fully Approved)" && Session["status"].ToString() == "PO Created")
            {
                ScriptManager.RegisterStartupScript(this, this.GetType(), "toastrMessage", "toastr.error('Cannot be Canceled!, This RF has issued a PO.');", true);
            }
            else if (Session["status"].ToString() == "Canceled")
            {
                ScriptManager.RegisterStartupScript(this, this.GetType(), "toastrMessage", "toastr.error('Operation Failed!, This RF has been Canceled.');", true);
            }
            else
            {

                string reason = hfCancelReason.Value;

                string path = ConfigurationManager.ConnectionStrings["dbpath"].ConnectionString;
                SqlConnection Con = new SqlConnection(path);
                Con.Open();
                SqlCommand sqlcomm = new SqlCommand();
                sqlcomm.CommandText = "sp_PROCUREMENT_DB_Purchase";
                sqlcomm.CommandType = CommandType.StoredProcedure;
                sqlcomm.Connection = Con;
                sqlcomm.Parameters.AddWithValue("@StatementType", "CancelRF");
                sqlcomm.Parameters.AddWithValue("@rf_no", lbRFNumberBreadcrumb.Text.Trim());
                sqlcomm.Parameters.AddWithValue("@nik_approver", Session["nik"].ToString());
                sqlcomm.Parameters.AddWithValue("@reasoncancel",reason ?? "");

                sqlcomm.ExecuteNonQuery();

                await SendEmailCancel();
                sqlcomm.Dispose();
                Con.Close();
                Con.Dispose();
            }
        }
    }
}